{
  "case_id": "C07",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook",
      "narration": "About one in three people with major depression don't get better on the first antidepressant they try. Could a routine blood test hint at who?",
      "on_screen": "Title card: 'Can a blood test predict antidepressant response?' Simple icon of three figures, one highlighted.",
      "claim_refs": ["Background: roughly one third of patients with MDD do not respond to a first-line SSRI"]
    },
    {
      "beat": "The study and the finding",
      "narration": "Researchers followed 512 adults starting an SSRI and measured interleukin-6, a marker of inflammation, once at the start. Twelve weeks later, 58 percent of those in the lowest IL-6 third had responded, compared with just 34 percent in the highest third.",
      "on_screen": "Two bar columns: low IL-6 group 58%, high IL-6 group 34%. Caption: 512 adults, 12 weeks, adjusted odds ratio 0.41 (95% CI 0.27-0.63).",
      "claim_refs": ["Abstract: 512 adults, 34% vs 58%, adjusted OR 0.41 (0.27-0.63)", "Methods: IL-6 measured once at baseline; response = 50% reduction in HAM-D", "Results: response by tertile; adjusted odds ratio"]
    },
    {
      "beat": "The proposed mechanism",
      "narration": "The team proposes an explanation: high IL-6 might push tryptophan, the raw material for serotonin, down a different route called the kynurenine pathway, leaving less serotonin available in the brain.",
      "on_screen": "Animated fork in a pipeline: tryptophan splitting toward 'serotonin' and 'kynurenine', with a dashed 'PROPOSED' stamp over the diagram.",
      "claim_refs": ["Abstract: we propose that elevated peripheral IL-6 reduces central serotonin availability via the kynurenine pathway", "Study design: proposed, untested mechanism"]
    },
    {
      "beat": "Why that stays a hypothesis",
      "narration": "But that is a hypothesis, not a result. No kynurenine metabolites were measured in this study, and nobody altered anyone's IL-6. Because it only observed people, inflammation could simply travel alongside whatever really drives poor response.",
      "on_screen": "Checklist: 'Kynurenine metabolites measured: none' / 'IL-6 not manipulated' / 'Observational cohort' — each with a cross.",
      "claim_refs": ["Results: kynurenine metabolites measured = None", "Methods: no metabolite panel was run; IL-6 was not manipulated", "Limitations: observational cohort; single baseline IL-6 measurement"]
    },
    {
      "beat": "Takeaway",
      "narration": "So: a real and reasonably strong association, measured with a widely available test, and worth following up in proper trials. Not yet something that should change anyone's prescription.",
      "on_screen": "Closing card: 'Association, not causation. Promising marker - needs testing.'",
      "claim_refs": ["Discussion: candidate stratification marker; widely available blood assay", "Conclusion: higher baseline IL-6 associated with lower SSRI response; mechanism proposed"]
    }
  ]
}
